window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[355]={"id":"355","numero":355,"titre":"Hémorragie digestive","objectifs":[{"id":"355-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’hémorragie digestive haute et basse","contenu":"<p>Une <span class=\"kw-def\">hémorragie digestive</span> est un <span class=\"kw-clinique\">saignement</span> ayant pour point de départ une partie du <span class=\"kw-def\">tube digestif</span>. Le repère anatomique qui sépare haute et basse est l'<span class=\"kw-def\">angle duodéno-jéjunal</span> (<span class=\"kw-def\">angle de Treitz</span>).</p>\n      <table >\n        <thead><tr><th>Type</th><th>Origine</th><th>Proportion</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Hémorragie digestive <span class=\"kw-def\">haute</span></strong></td><td>En <strong>amont</strong> de l'<span class=\"kw-def\">angle de Treitz</span></td><td><span class=\"kw-chiffre\">80 %</span> des hémorragies digestives</td></tr>\n          <tr><td><strong>Hémorragie digestive <span class=\"kw-def\">basse</span></strong></td><td>En <strong>aval</strong> de l'<span class=\"kw-def\">angle de Treitz</span></td><td><span class=\"kw-chiffre\">20 %</span> des hémorragies digestives</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'<span class=\"kw-def\">angle de Treitz</span> (jonction <span class=\"kw-def\">duodéno-jéjunale</span>) est la frontière haut/bas. La très grande majorité des hémorragies digestives sont <span class=\"kw-def\">hautes</span> (<span class=\"kw-chiffre\">80 %</span>).</div>","frequence":0},{"id":"355-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie des hémorragies hautes et basses, en fonction du terrain et des facteurs de risque","contenu":"<table >\n        <thead><tr><th>Paramètre</th><th>HD haute</th><th>HD basse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Sex-ratio</strong></td><td>Prédominance <span class=\"kw-clinique\">masculine</span> (avant <span class=\"kw-chiffre\">80 ans</span>)</td><td>Prédominance <span class=\"kw-clinique\">masculine</span></td></tr>\n          <tr><td><strong>Âge</strong></td><td>Âge médian des hospitalisés : <span class=\"kw-chiffre\">70 ans</span></td><td><span class=\"kw-def\">Incidence</span> ↑ nettement avec l'âge ; âge moyen <span class=\"kw-chiffre\">70 ans</span></td></tr>\n          <tr><td><strong><span class=\"kw-def\">Mortalité</span></strong></td>\n            <td><strong>Globale :</strong> <span class=\"kw-chiffre\">3-10 %</span> (↑ avec âge et <span class=\"kw-def\">comorbidités</span>)<br><strong>Si <span class=\"kw-etio\">UGD</span> :</strong> <span class=\"kw-chiffre\">2,5-5 %</span><br><strong>Si <span class=\"kw-etio\">HTP</span> :</strong> <span class=\"kw-chiffre\">10-20 %</span> à<span class=\"kw-chiffre\"> 6 semaines</span></td>\n            <td><strong>Globale :</strong> <span class=\"kw-chiffre\">2-8 %</span> (liée à l'âge et <span class=\"kw-def\">comorbidités</span>)<br><strong><span class=\"kw-clinique\">Évolution</span> :</strong> arrêt spontané dans <span class=\"kw-chiffre\">70 %</span> des cas ; récidive fréquente<br><strong>Topographie :</strong> colon/rectum/anus dans <span class=\"kw-chiffre\">90 %</span> des cas</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> L'HD basse s'arrête <strong>spontanément dans <span class=\"kw-chiffre\">70 %</span></strong> des cas — mais récidive souvent et reste majoritairement <span class=\"kw-clinique\">colo-recto-anale</span> (<span class=\"kw-chiffre\">90 %</span>).</div>","frequence":0},{"id":"355-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modes de révélation clinique (hématémèse, méléna, hématochézie, choc hémorragique)","contenu":"<table >\n        <thead><tr><th>Mode</th><th>Description et valeur localisatrice</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Hématémèse</span></strong></td><td>Extériorisation de sang lors d'un effort de <span class=\"kw-clinique\">vomissement</span>. Traduit <strong>toujours</strong> une <span class=\"kw-def\">hémorragie digestive haute</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Méléna</span></strong></td><td>Émission par l'anus de sang <span class=\"kw-clinique\">digéré, noir et fétide</span> (aspect goudron) ; peut passer inaperçu (rechercher au <span class=\"kw-clinique\">TR</span>). Origine en amont de l'angle colique droit → <span class=\"kw-clinique\">haute dans <span class=\"kw-chiffre\">80 %</span></span> des cas, ou basse.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Rectorragie</span> / <span class=\"kw-clinique\">Hématochézie</span></strong></td><td>Sang <span class=\"kw-clinique\">rouge</span> : soit <span class=\"kw-clinique\">HD basse</span>, soit <span class=\"kw-alerte\">HD haute massive</span> (ex. ulcère duodénal érodant l'<span class=\"kw-clinique\">artère duodénale postérieure</span>).</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Choc hémorragique</span> sans extériorisation</strong></td><td><strong>Signes :</strong> <span class=\"kw-clinique\">tachycardie</span> ; <span class=\"kw-clinique\">hypotension</span> ; mauvais rendement transfusionnel (<span class=\"kw-chiffre\">> 2 CGR/24h</span> pour maintenir Hb <span class=\"kw-chiffre\">> 7 g/dL</span>).<br><strong>Diagnostic :</strong> <span class=\"kw-clinique\">sonde gastrique</span> ; recherche de sang au <span class=\"kw-clinique\">TR</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant.</strong> L'<span class=\"kw-clinique\">hématémèse</span> = toujours une hémorragie <strong>haute</strong>. Une <span class=\"kw-clinique\">rectorragie</span> abondante peut révéler une HD <strong>haute massive</strong>, pas seulement basse.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"355-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic d’une hémorragie digestive haute ou basse","contenu":"<table >\n        <thead><tr><th>Signe</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Hématémèse</span></strong></td><td>Sang rouge ou digéré lors d'un effort de <span class=\"kw-clinique\">vomissement</span> → <span class=\"kw-alerte\">HD haute</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Méléna</span></strong></td><td>Selles noires fétides → haute (<span class=\"kw-chiffre\">80 %</span>) ou basse. <strong>Piège :</strong> la <span class=\"kw-clinique\">supplémentation en fer per os</span> noircit <span class=\"kw-clinique\">les</span> selles et simule un <span class=\"kw-clinique\">méléna</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Rectorragie</span> / <span class=\"kw-clinique\">hématochézie</span></strong></td><td>Sang rouge → basse, ou haute massive.</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Choc</span> sans extériorisation</strong></td><td><span class=\"kw-clinique\">Tachycardie</span>, hypotension, mauvais rendement transfusionnel → diagnostic par <span class=\"kw-clinique\">SNG</span> et <span class=\"kw-clinique\">TR</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Hémorragie occulte</span></strong></td><td><span class=\"kw-bio\">Anémie ferriprive</span> chronique : situation rarement aiguë, prise en charge moins urgente.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>SNG, prudence.</strong> La <span class=\"kw-clinique\">sonde nasogastrique</span> affirme l'HD haute si elle ramène un liquide <span class=\"kw-clinique\">sanglant vif</span> — mais l'<strong>absence de saignement n'élimine pas une HD haute post-bulbaire</strong>.</div>\n      <p><strong>Diagnostics différentiels à éliminer :</strong></p>\n      <ul>\n        <li><strong>De l'<span class=\"kw-clinique\">hématémèse</span> :</strong> <span class=\"kw-clinique\">hémoptysie</span> ; <span class=\"kw-clinique\">épistaxis postérieure déglutie</span> ; <span class=\"kw-clinique\">vomissements</span> alimentaires rouges (vin rouge, betteraves, grenadine).</li>\n        <li><strong>De l'HD basse :</strong> <span class=\"kw-clinique\">ulcération thermométrique</span> (pédiatrie) ; <span class=\"kw-clinique\">supplémentation en fer</span> (faux <span class=\"kw-clinique\">méléna</span>).</li>\n      </ul>","frequence":1},{"id":"355-5","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic et les étiologies des hématémèses de l’enfant","contenu":"<table >\n        <thead><tr><th>Âge</th><th>Étiologies d'<span class=\"kw-clinique\">hématémèse</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nouveau-né</strong></td><td><span class=\"kw-etio\">Œsogastrite néonatale</span> (stress maternel, médicaments au 3ᵉ trimestre, aspiration traumatique) ; <span class=\"kw-etio\">déglutition de sang issu de crevasses maternelles</span> (<span class=\"kw-ci\">allaitement</span>).</td></tr>\n          <tr><td><strong>Nourrisson</strong></td><td>Déglutition de sang de <span class=\"kw-etio\">crevasses maternelles</span> ; <span class=\"kw-etio\">œsophagite peptique</span> par reflux (plus rare).</td></tr>\n          <tr><td><strong>Enfant</strong></td><td><span class=\"kw-etio\">Syndrome de Mallory-Weiss</span> (<span class=\"kw-clinique\">vomissements</span> répétés et prolongés) : fréquent ; <span class=\"kw-etio\">ulcère</span> (duodénal avant tout), <span class=\"kw-etio\">gastrite</span> médicamenteuse (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">corticoïdes</span>).</td></tr>\n          <tr><td><strong>Plus rare</strong></td><td><span class=\"kw-alerte\">Rupture</span> de <span class=\"kw-etio\">varices œsophagiennes</span> sur <span class=\"kw-etio\">hypertension portale</span> (atrésie des voies biliaires, cirrhose métabolique <span class=\"kw-etio\">héréditaire</span>, mucoviscidose).</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>DD majeur.</strong> L'<span class=\"kw-clinique\">épistaxis déglutie</span> est plus fréquente que l'<span class=\"kw-clinique\">hématémèse</span> vraie. L'<span class=\"kw-imagerie\">EOGD</span> est inutile en cas de <span class=\"kw-etio\">Mallory-Weiss</span> typique.</div>","frequence":0},{"id":"355-6","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les éléments du diagnostic et les étiologies des hémorragies digestives basses de l’enfant","contenu":"<p><strong>Cause principale : <span class=\"kw-etio\">fissure anale sur constipation</span>.</strong></p>\n      <ul>\n        <li><strong>Manifestation :</strong> émission de sang <span class=\"kw-clinique\">rouge</span> lors de l'exonération, <strong>non mélangé</strong> aux selles.</li>\n        <li><strong>Diagnostic :</strong> <span class=\"kw-clinique\">clinique</span> (anamnèse + examen), <strong>pas d'examen complémentaire</strong>.</li>\n        <li><strong>Drapeau :</strong> fissure chez le grand enfant → rechercher des arguments pour une <span class=\"kw-etio\">maladie de Crohn</span> (cassure de la courbe, troubles du transit, aphtes).</li>\n      </ul>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Étiologies d'HD basse</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nouveau-né</strong></td><td><span class=\"kw-etio\">Entérocolite ulcéro-nécrosante</span> (prématuré) ; <span class=\"kw-etio\">diarrhées infectieuses</span> (<span class=\"kw-etio\">campylobacter</span>).</td></tr>\n          <tr><td><strong>Nourrisson / enfant</strong></td><td><span class=\"kw-etio\">Invagination intestinale aiguë</span> → <span class=\"kw-ttt\">réduction</span> par lavement ; <span class=\"kw-etio\">diverticule de Meckel</span> → <span class=\"kw-ttt\">chirurgie</span>.</td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-etio\">Colites</span> et <span class=\"kw-etio\">diarrhées infectieuses</span> ; <span class=\"kw-etio\">maladie de Crohn</span> (grand enfant) ; causes <span class=\"kw-etio\">traumatiques</span>.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 282 — <span class=\"kw-clinique\">MICI</span></em></p>","frequence":0},{"id":"355-7","rang":"A","rubrique":"Etiologies","titre":"Savoir que la cause la plus fréquente d’hémorragie digestive haute est l’ulcération gastro duodénale","contenu":"<p>La cause la plus fréquente d'<span class=\"kw-def\">hémorragie digestive haute</span> est l'<span class=\"kw-etio\">ulcération gastro-duodénale</span>.</p>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Ulcères / ulcérations gastro-duodénales</span> :</strong> <span class=\"kw-chiffre\">30-60 %</span> des HD hautes = <strong>1ʳᵉ cause</strong>.</li>\n        <li><strong><span class=\"kw-etio\">Érosions gastro-duodénales</span> :</strong> <span class=\"kw-chiffre\">7-20 %</span>.</li>\n      </ul>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant toute HD haute, l'<span class=\"kw-etio\">UGD</span> est le premier diagnostic à évoquer — et impose la recherche systématique d'<span class=\"kw-bio\">Helicobacter pylori</span>.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span></em></p>","frequence":0},{"id":"355-8","rang":"A","rubrique":"Etiologies","titre":"Connaître les principales causes d’hémorragie digestives","contenu":"<p><strong>Hémorragies digestives <span class=\"kw-def\">hautes</span></strong></p>\n      <table >\n        <thead><tr><th>Niveau</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Principales</strong></td><td><span class=\"kw-etio\">Ulcères / ulcérations gastro-duodénales</span> (<span class=\"kw-chiffre\">30-60 %</span>) ; <span class=\"kw-etio\">érosions gastro-duodénales</span> (<span class=\"kw-chiffre\">7-20 %</span>) ; <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-etio\">varices œsophagiennes</span> ou cardio-tubérositaires, <span class=\"kw-etio\">gastropathie d'HTP</span> (<span class=\"kw-chiffre\">3-20 %</span>).</td></tr>\n          <tr><td><strong>Autres</strong></td><td><span class=\"kw-etio\">Œsophagite</span> (<span class=\"kw-chiffre\">1-10 %</span> ; peptique, médicamenteuse, caustique) ; <span class=\"kw-etio\">cancers</span> du tractus digestif supérieur (<span class=\"kw-chiffre\">2-5 %</span>) ; <span class=\"kw-etio\">syndrome de Mallory-Weiss</span> (<span class=\"kw-chiffre\">2-4 %</span>, <span class=\"kw-clinique\">vomissements</span> initiaux).</td></tr>\n          <tr><td><strong>Plus rares</strong></td><td><span class=\"kw-etio\">Gastrites</span> ; <span class=\"kw-etio\">angiodysplasies</span> ; <span class=\"kw-etio\">ulcération de Dieulafoy</span> (<span class=\"kw-clinique\">ulcération</span> en regard d'une artère sous-muqueuse dilatée) ; <span class=\"kw-etio\">hémobilies</span>, <span class=\"kw-etio\">wirsungorragies</span>, <span class=\"kw-alerte\">fistules aorto-digestives</span>.</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Hémorragies digestives <span class=\"kw-def\">basses</span></strong></p>\n      <table >\n        <thead><tr><th>Siège</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Intestin grêle (<span class=\"kw-chiffre\">< 10 %</span>)</strong></td><td><span class=\"kw-etio\">Diverticule de Meckel</span> (<span class=\"kw-chiffre\">40 %</span>) ; <span class=\"kw-etio\">angiodysplasies</span> ; <span class=\"kw-etio\">ulcérations</span> (favorisées par <span class=\"kw-ttt\">AINS</span>) ; <span class=\"kw-etio\">MICI</span> (Crohn) en poussée ; <span class=\"kw-etio\">tumeurs</span> ; <span class=\"kw-etio\">maladie de Rendu-Osler</span>.</td></tr>\n          <tr><td><strong>Colon-rectum-anus (<span class=\"kw-chiffre\">> 80-90 %</span>)</strong></td><td><span class=\"kw-etio\">Maladie diverticulaire</span> = <strong>1ʳᵉ cause</strong> (<span class=\"kw-chiffre\">40 %</span>) ; <span class=\"kw-alerte\">tumeur colique ou rectale</span> (maligne à éliminer systématiquement) ; <span class=\"kw-etio\">colites</span> (ischémiques, infectieuses, radiques, MICI) ; <span class=\"kw-etio\">angiodysplasies coliques</span> ; <span class=\"kw-etio\">maladie hémorroïdaire</span> ; <span class=\"kw-etio\">fissure anale</span> ; HD basse sur <span class=\"kw-etio\">hypertension portale</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Réflexe.</strong> Devant une HD basse, la <span class=\"kw-alerte\">tumeur colo-rectale</span> doit être éliminée systématiquement — la maladie hémorroïdaire ne dispense jamais d'une <span class=\"kw-imagerie\">coloscopie</span> complète.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - gastrite · 287 — Diverticulose colique - diverticulite aiguë · 301 — Tumeur colon - rectum · 282 — MICI</em></p>","frequence":0},{"id":"355-9","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens biologiques à réaliser devant une hémorragie digestive","contenu":"<ul>\n        <li><strong><span class=\"kw-bio\">NFS</span> :</strong> <span class=\"kw-bio\">hémoglobine</span>, <span class=\"kw-bio\">hématocrite</span> — peuvent <strong>sous-estimer</strong> initialement l'abondance du saignement.</li>\n        <li><strong><span class=\"kw-bio\">Ionogramme</span></strong>, <strong><span class=\"kw-bio\">créatinine</span></strong>, <strong><span class=\"kw-bio\">calcémie</span></strong>.</li>\n        <li><strong><span class=\"kw-bio\">Bilan d'hémostase</span></strong> (<span class=\"kw-bio\">TP</span>, <span class=\"kw-bio\">TCA</span>, <span class=\"kw-bio\">plaquettes</span>, <span class=\"kw-bio\">fibrinogène</span>).</li>\n        <li><strong><span class=\"kw-bio\">Bilan pré-transfusionnel</span> :</strong> <span class=\"kw-bio\">2 déterminations de groupe sanguin</span> + <span class=\"kw-bio\">RAI</span>.</li>\n        <li><strong>± <span class=\"kw-bio\">Gaz du sang</span></strong> selon l'état clinique.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Une <span class=\"kw-bio\">hémoglobine</span> normale à l'arrivée <strong>n'élimine pas</strong> une hémorragie grave — elle peut être normale <strong>avant remplissage</strong> (hémoconcentration).</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 329 — Transfusion sanguine</em></p>","frequence":0},{"id":"355-10","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens d’imagerie devant une hémorragie digestive","contenu":"<table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">EOGD</span></strong></td><td>Examen de 1ʳᵉ intention de l'HD haute : diagnostic lésionnel dans <span class=\"kw-chiffre\">90 %</span> des cas, pronostique et thérapeutique.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Angio-TDM abdomino-pelvien</span></strong></td><td>Indiqué devant des <span class=\"kw-clinique\">rectorragies / hématochézies sévères</span> si : <span class=\"kw-imagerie\">EOGD</span> non rapidement disponible ; ou <span class=\"kw-alerte\">fistule aorto-digestive</span> suspectée (ATCD de <span class=\"kw-ttt\">chirurgie</span> de l'aorte abdominale).</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Coloscopie</span></strong></td><td>HD basse, sans <span class=\"kw-alerte\">urgence</span>, après <strong>préparation colique</strong> (régime sans résidus, laxatifs).</td></tr>\n          <tr><td><strong>2ⁿᵈᵉ intention (« saignement obscur »)</strong></td><td><span class=\"kw-imagerie\">Vidéocapsule endoscopique</span> ou <span class=\"kw-imagerie\">entéro-TDM</span> — la <span class=\"kw-imagerie\">coloscopie</span> ne dépasse pas l'<span class=\"kw-clinique\">iléon</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>À ne pas faire.</strong> Pas de <span class=\"kw-bio\">recherche de sang occulte dans les selles</span> ici — ce test est réservé au <span class=\"kw-def\">dépistage</span> de <span class=\"kw-clinique\">masse</span> du cancer colorectal chez l'asymptomatique.</div>","frequence":1},{"id":"355-11","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les signes de gravité d’une hémorragie digestive haute ou basse chez l’adulte et l’enfant","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> La <span class=\"kw-clinique\">tachycardie</span> est le <strong>meilleur signe précoce</strong> de <span class=\"kw-alerte\">défaillance</span> hémodynamique débutante — signe d'alerte majeur devant toute hémorragie.</div>\n      <p><strong><span class=\"kw-alerte\">Signes de gravité</span> (tombés en annale) :</strong></p>\n      <ul>\n        <li><span class=\"kw-alerte\">Tachycardie > <span class=\"kw-chiffre\">100 bpm</span></span> (attention aux patients sous <span class=\"kw-ttt\">β-bloquants</span>) ; la <span class=\"kw-alerte\">bradycardie</span> est un <span class=\"kw-alerte\">signe de gravité</span> extrême ; <span class=\"kw-clinique\">hypotension</span>.</li>\n        <li>Signes d'<span class=\"kw-clinique\">hypoperfusion périphérique</span> : <span class=\"kw-clinique\">marbrures</span> ; <span class=\"kw-clinique\">↑ TRC</span> ; <span class=\"kw-clinique\">oligurie</span> <span class=\"kw-chiffre\">< 0,5 mL/kg/h</span>.</li>\n        <li>Neuro / général : <span class=\"kw-clinique\">malaise</span>, <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">agitation</span>, <span class=\"kw-clinique\">coma</span>, lipothymie, chute, <span class=\"kw-clinique\">polypnée</span>, <span class=\"kw-clinique\">pâleur cutanéo-muqueuse</span>.</li>\n      </ul>\n      <div class=\"callout callout-warn\"><strong>Pièges — gravité sous-estimée si jugée sur :</strong>\n        <ul>\n          <li>La <strong>quantité de sang extériorisé</strong> = <span class=\"kw-alerte\">mauvais critère</span> (tombé en annale).</li>\n          <li>L'<span class=\"kw-bio\">Hb</span> / l'<span class=\"kw-bio\">hématocrite</span> : <strong>sous-estiment</strong> initialement l'abondance.</li>\n          <li>Chez le <strong>sujet jeune</strong> qui compense l'hypovolémie par une <span class=\"kw-clinique\">tachycardie</span> (hypotension retardée).</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 332 — Etat de choc</em></p>","frequence":2},{"id":"355-12","rang":"A","rubrique":"Identifier une urgence","titre":"Connaître les diagnostics urgents devant une hémorragie digestive basse : invagination intestinale aiguë (basse), diverticule de Meckel","contenu":"<div class=\"callout callout-danger\"><strong>Deux urgences pédiatriques à reconnaître devant une HD basse.</strong></div>\n      <table >\n        <thead><tr><th>Diagnostic</th><th>Points clés</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Invagination intestinale aiguë</span> (basse)</strong></td><td><span class=\"kw-alerte\">Urgence</span>, surtout chez le <span class=\"kw-clinique\">nourrisson</span> ; révélation par <span class=\"kw-clinique\">occlusion</span> ± hémorragie → <strong><span class=\"kw-ttt\">réduction</span> par <span class=\"kw-imagerie\">lavement</span></strong>.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Diverticule de Meckel</span></strong></td><td>1ʳᵉ cause d'HD du grêle (<span class=\"kw-chiffre\">40 %</span>) ; révélation par <span class=\"kw-clinique\">hémorragie</span> (plutôt adulte) ou <span class=\"kw-clinique\">occlusion</span> (plutôt enfant) → <strong><span class=\"kw-ttt\">chirurgie</span></strong>.</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"355-13","rang":"A","rubrique":"Prise en charge","titre":"Connaître et prévenir les principaux facteurs de risques de saignement","contenu":"<table >\n        <thead><tr><th><span class=\"kw-def\">Facteur de risque</span></th><th>Mécanisme / chiffres</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Hypertension portale</span></strong></td><td>Risque de <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-etio\">varices œsophagiennes</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">Helicobacter pylori</span></strong></td><td><strong>À rechercher systématiquement</strong> devant toute HD haute.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">AINS</span></strong></td><td>Complications ulcéreuses <span class=\"kw-chiffre\">×3-4</span> ; complications fatales <span class=\"kw-chiffre\">×7-8</span>. <span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">anti-COX2</span> réduisent de <span class=\"kw-chiffre\">50 %</span> les événements GI graves <span class=\"kw-bio\">vs</span> <span class=\"kw-ttt\">AINS</span> non sélectifs. Favorisent aussi les HD <strong>basses</strong>.</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Antithrombotiques</span></strong></td><td><span class=\"kw-ttt\">Aspirine</span> : toxicité digestive dose-dépendante, <strong>dès <span class=\"kw-chiffre\">< 100 mg/j</span></strong>. Autres <span class=\"kw-ttt\">AAP</span> et <span class=\"kw-ttt\">anticoagulants</span> aggravent le saignement de lésions existantes (y compris basses).</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Sérotoninergiques (ISRS)</span></strong></td><td>Blocage de la recapture plaquettaire de sérotonine → <span class=\"kw-alerte\">trouble de l'hémostase primaire</span> ; risque surtout chez le sujet âgé, ATCD ulcéreux, ou co-prescription d'<span class=\"kw-ttt\">AINS</span>.</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — Cirrhose</em></p>","frequence":1},{"id":"355-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge thérapeutique en urgence des hémorragies digestives et de leurs complications y compris chez le cirrhotique","contenu":"<p><strong>1 · Premières mesures de <span class=\"kw-alerte\">réanimation</span> (tombé en annale)</strong></p>\n      <ul>\n        <li><strong>Voies :</strong> <span class=\"kw-chiffre\">2 VVP</span> de bon calibre + assurer une bonne <span class=\"kw-clinique\">oxygénation</span>.</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span> continue :</strong> <span class=\"kw-clinique\">SaO2</span>, <span class=\"kw-clinique\">pouls</span>, <span class=\"kw-clinique\">PA</span>, <span class=\"kw-clinique\">diurèse</span>.</li>\n        <li><strong>Bilan :</strong> <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">bilan pré-transfusionnel</span> (<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> G</span>S + RAI) ± <span class=\"kw-bio\">GDS</span>.</li>\n        <li><strong>Antithrombotiques :</strong> <span class=\"kw-ttt\">arrêt</span> ± <span class=\"kw-ttt\">antagonisation</span> des <span class=\"kw-ttt\">anticoagulants</span> ; arrêt de l'<span class=\"kw-ttt\">AAP</span> à discuter avec le cardiologue si <span class=\"kw-alerte\">stent récent (< 1 mois)</span>.</li>\n      </ul>\n\n      <p><strong>2 · Orientation (tombé en annale)</strong></p>\n      <table >\n        <thead><tr><th>Profil</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td>Patient <span class=\"kw-clinique\">stable</span> (FC normale, sans saignement actif, sans forte déglobulisation ni comorbidité majeure)</td><td>Hospitalisation en <strong>service conventionnel</strong>.</td></tr>\n          <tr><td>Patient <span class=\"kw-alerte\">tachycarde</span>, saignement actif/abondant, comorbidités, <span class=\"kw-alerte\">état de choc</span></td><td>Appel du <strong>réanimateur</strong> + hospitalisation en <strong>USI / réanimation</strong>.</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>3 · Si choc hémorragique (tombé en annale)</strong></p>\n      <div class=\"callout callout-danger\"><strong>Choc hémorragique.</strong> <span class=\"kw-ttt\">Remplissage</span> (cristalloïde) ± <span class=\"kw-ttt\">noradrénaline</span> (si <span class=\"kw-chiffre\">PAS < 80 mmHg</span> malgré <span class=\"kw-chiffre\">1-1,5 L</span>) ± <span class=\"kw-ttt\">transfusion sanguine</span>. Objectifs :\n        <ul>\n          <li><span class=\"kw-clinique\">FC</span> <span class=\"kw-chiffre\">< 100 bpm</span></li>\n          <li><span class=\"kw-clinique\">PAS > 100 mmHg</span> ou <span class=\"kw-clinique\">PAM ≥ 65 mmHg</span> (sauf saignement non contrôlé : viser <span class=\"kw-chiffre\">PAS 80-90 mmHg</span>)</li>\n          <li><span class=\"kw-clinique\">Diurèse</span> <span class=\"kw-chiffre\">> 30 mL/h</span> (ou <span class=\"kw-chiffre\">> 0,5 mL/kg/h</span>)</li>\n          <li><strong><span class=\"kw-bio\">Hb cible</span> :</strong> <span class=\"kw-chiffre\">7-9 g/dL</span> en général ; <span class=\"kw-chiffre\">7-8 g/dL</span> si <span class=\"kw-etio\">varices œsophagiennes</span> ; <span class=\"kw-chiffre\">> 9 g/dL</span> si comorbidités cardio-vasculaires.</li>\n        </ul>\n      </div>\n\n      <p><strong>4 · Mesures médicamenteuses spécifiques de l'HD haute</strong></p>\n      <table >\n        <thead><tr><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">IPP</span></strong></td><td><strong>Bolus puis IVSE chez TOUS</strong> les patients d'HD haute (même porteurs d'<span class=\"kw-etio\">HTP</span>), en présomptif dès l'admission sans retarder l'<span class=\"kw-imagerie\">endoscopie</span>. Adaptation selon le score de <span class=\"kw-def\">Forrest</span> : pas d'ulcère → arrêt ; <span class=\"kw-def\">Forrest 2c-3</span> → relais précoce per os pleine dose ; <span class=\"kw-def\">Forrest 1a-2b</span> → fortes doses IV continu <span class=\"kw-chiffre\">48-72h</span> puis relais per os.</td></tr>\n          <tr><td><strong>Pré-hospitalier (si <span class=\"kw-etio\">HTP</span>)</strong></td><td><span class=\"kw-ttt\">Octréotide</span> (analogue de la somatostatine) ou <span class=\"kw-ttt\">terlipressine</span> (analogue de la vasopressine) si hépatopathie chronique ou HTP connue/suspectée.</td></tr>\n          <tr><td><strong>Si <span class=\"kw-etio\">cirrhose</span> / HTP</strong></td><td><span class=\"kw-ttt\">Antibioprophylaxie</span> : <span class=\"kw-ttt\">norfloxacine</span> ou <span class=\"kw-ttt\">céfotaxime</span> pendant <span class=\"kw-chiffre\">5-7 jours</span>.</td></tr>\n          <tr><td><strong>Si <span class=\"kw-etio\">alcoolisme</span></strong></td><td>Prévention du syndrome de sevrage : hydratation + <span class=\"kw-ttt\">vitamines B1 / B6 / PP</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>5 · Endoscopie (<span class=\"kw-imagerie\">EOGD</span>) et gestes d'hémostase</strong></p>\n      <ul>\n        <li><strong>Timing :</strong> après <span class=\"kw-alerte\">stabilisation</span> du patient instable ; en urgence si HD haute active instable ou rectorragies sévères ; semi-urgence <span class=\"kw-chiffre\">< 24h</span> (haute, stable) ou <span class=\"kw-chiffre\">< 12h</span> si suspicion de rupture de <span class=\"kw-etio\">varices œsophagiennes</span>.</li>\n        <li><strong>Préparation :</strong> <span class=\"kw-ttt\">érythromycine IV</span> <span class=\"kw-chiffre\">30-60 min</span> avant (effet prokinétique) — <span class=\"kw-ci\">contre-indiquée si QT long</span>.</li>\n        <li><strong>Gestes d'hémostase :</strong> pharmacologiques (<span class=\"kw-ttt\">sérum adrénaliné</span>), mécaniques (<span class=\"kw-ttt\">clip</span>, <span class=\"kw-ttt\">ligature de varice</span>), thermiques (<span class=\"kw-ttt\">électrocoagulation</span>).</li>\n      </ul>\n\n      <p><strong>6 · En cas d'échec</strong></p>\n      <ul>\n        <li><span class=\"kw-ttt\">Artério-embolisation</span> en radiologie interventionnelle (si <span class=\"kw-imagerie\">angio-TDM</span> positif).</li>\n        <li><span class=\"kw-ttt\">Gastrectomie d'hémostase</span> (exceptionnelle, mortalité <span class=\"kw-chiffre\">10-20 %</span> ; si choc initial non contrôlé, position bulbaire de l'ulcère).</li>\n        <li><span class=\"kw-ttt\">TIPS</span> (shunt porto-systémique) pour la rupture de <span class=\"kw-etio\">varices œso-gastriques</span> — risque d'induire/majorer une <span class=\"kw-alerte\">encéphalopathie hépatique</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Chez le cirrhotique.</strong> L'<span class=\"kw-ttt\">octréotide</span> est <strong>poursuivi</strong> en cas de rupture de <span class=\"kw-etio\">varices œsophagiennes</span>, puis <strong>relayé par <span class=\"kw-ttt\">β-bloquants</span></strong> en prévention secondaire. Antibioprophylaxie systématique.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 279 — Cirrhose · 332 — Etat de choc · 329 — Transfusion sanguine</em></p>","frequence":13},{"id":"355-15","rang":"B","rubrique":"Prise en charge","titre":"Hématémèse de l’enfant : connaître les modalités de traitement","contenu":"<ul>\n        <li><strong>Traitement symptomatique :</strong> <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">hématémèses</span> sont <strong>rarement sévères</strong> en pédiatrie. Si forme sévère → <span class=\"kw-alerte\">soins intensifs</span> (scope, <span class=\"kw-clinique\">voie veineuse</span>, <span class=\"kw-ttt\">remplissage</span>, éventuellement <span class=\"kw-ttt\">transfusion</span>).</li>\n        <li><strong>Traitement étiologique :</strong>\n          <ul>\n            <li><span class=\"kw-etio\">Œsophagite</span> ou <span class=\"kw-etio\">ulcère</span> → <span class=\"kw-ttt\">IPP</span> + traitement d'<span class=\"kw-bio\">H. pylori</span> le cas échéant.</li>\n            <li>Sang dégluti de <span class=\"kw-etio\">crevasses maternelles</span> → soins des crevasses de la mère + conseils de positionnement pour l'<span class=\"kw-ci\">allaitement</span>.</li>\n          </ul>\n        </li>\n        <li><strong>Explorations :</strong> <span class=\"kw-imagerie\">EOGD</span> en <span class=\"kw-alerte\">urgence</span> si hémorragie non contrôlée, nécessaire pour œsophagite/ulcère, <strong>non nécessaire si <span class=\"kw-etio\">Mallory-Weiss</span></strong>.</li>\n      </ul>","frequence":0},{"id":"355-16","rang":"B","rubrique":"Prise en charge","titre":"Hémorragie digestive basse de l’enfant : connaître modalités de traitement","contenu":"<table >\n        <thead><tr><th>Cause</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Fissure sur constipation</span></strong></td><td>Traitement de la <span class=\"kw-clinique\">constipation</span> (<span class=\"kw-ttt\">laxatifs</span>).</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Invagination intestinale aiguë</span></strong></td><td><span class=\"kw-ttt\">Réduction</span> par <span class=\"kw-imagerie\">lavement</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Diverticule de Meckel</span></strong></td><td><span class=\"kw-ttt\">Chirurgie</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Entérocolite</span> / <span class=\"kw-etio\">colites infectieuses</span></strong></td><td>Prise en charge <span class=\"kw-clinique\">étiologique</span>.</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"355-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître la place de l’endoscopie digestive (diagnostique et thérapeutique) dans les hémorragies digestives","contenu":"<p><strong><span class=\"kw-clinique\">Les</span> 3 objectifs de l'<span class=\"kw-imagerie\">EOGD</span> dans l'hémorragie digestive :</strong></p>\n      <table >\n        <thead><tr><th>Objectif</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Diagnostique</strong></td><td>Diagnostic lésionnel dans <span class=\"kw-chiffre\">90 %</span> des cas.</td></tr>\n          <tr><td><strong>Pronostique</strong></td><td><span class=\"kw-def\">Score</span> de <span class=\"kw-def\">Forrest</span> pour l'<span class=\"kw-etio\">ulcère</span> ; évaluation des <span class=\"kw-etio\">varices œsophagiennes</span>.</td></tr>\n          <tr><td><strong>Thérapeutique</strong></td><td>Geste d'<span class=\"kw-bio\">hémostase</span> : <span class=\"kw-ttt\">sérum adrénaliné</span>, <span class=\"kw-ttt\">clip</span>, <span class=\"kw-ttt\">ligature</span>, <span class=\"kw-ttt\">électrocoagulation</span>.</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Conditions de réalisation.</strong> L'<span class=\"kw-imagerie\">EOGD</span> se fait chez un patient <span class=\"kw-clinique\">stable</span> sur le plan hémodynamique : soit conscient/coopérant, soit sous <span class=\"kw-ttt\">AG avec induction à séquence rapide + IOT</span> (à privilégier si <span class=\"kw-alerte\">hémorragie massive</span>).</div>\n      <p>Pour l'HD basse : <span class=\"kw-imagerie\">coloscopie</span> complète après préparation ; en cas de saignement obscur, <span class=\"kw-imagerie\">vidéocapsule endoscopique</span> ou <span class=\"kw-imagerie\">entéro-TDM</span>.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 272 — Ulcère gastroduodénal - <span class=\"kw-clinique\">gastrite</span></em></p>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong><span class=\"kw-alerte\">Choc</span> <span class=\"kw-etio\">hémorragique</span> <span class=\"q\">— <span class=\"kw-alerte\">urgence</span> vitale</span></strong></p><p>appel du <strong>réanimateur</strong> ; l’<span class=\"kw-imagerie\">EOGD</span> n’est réalisée qu’<strong>après stabilisation</strong></p><ul><li>La <span class=\"kw-clinique\">tachycardie</span> est le <strong>meilleur signe précoce</strong> de <span class=\"kw-alerte\">défaillance</span> hémodynamique débutante</li><li><span class=\"kw-ttt\">Remplissage</span> (cristalloïdes) ± <span class=\"kw-ttt\">noradrénaline</span> si <span class=\"kw-chiffre\">PAS &lt; 80 mmHg</span> malgré <span class=\"kw-chiffre\">1-1,5 L</span> ± <span class=\"kw-ttt\">transfusion</span></li><li>Gravité <strong>sous-estimée</strong> si jugée sur la quantité de sang extériorisé (<span class=\"kw-alerte\">mauvais critère</span>) ou une <span class=\"kw-bio\">Hb</span> initiale normale (avant remplissage)</li></ul><p><strong><span class=\"kw-imagerie\">EOGD</span> en <span class=\"kw-alerte\">urgence</span> <span class=\"q\">— HD haute active instable</span></strong></p><ul><li>Réalisée <strong>après stabilisation</strong> hémodynamique</li><li><span class=\"kw-clinique\">Rectorragies sévères</span> → <span class=\"kw-imagerie\">angio-TDM</span> si <span class=\"kw-imagerie\">EOGD</span> non rapidement disponible ou <span class=\"kw-alerte\">fistule aorto-digestive</span> suspectée</li></ul><p><strong><span class=\"kw-imagerie\">EOGD</span> en semi-<span class=\"kw-alerte\">urgence</span> <span class=\"q\">— délais chiffrés</span></strong></p><ul><li>HD haute stable non à risque : <span class=\"kw-chiffre\">&lt; 24h</span></li><li>Suspicion de <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-etio\">varices œsophagiennes</span> (cirrhose / <span class=\"kw-clinique\">HTP</span>) : <span class=\"kw-chiffre\">&lt; 12h</span></li></ul>","hospit":"<p><strong>Service conventionnel</strong></p><ul><li>Patient <span class=\"kw-clinique\">stable</span>, FC normale, sans saignement actif</li><li>Sans forte déglobulisation ni <span class=\"kw-def\">comorbidité</span> majeure</li></ul><p><strong><span class=\"kw-alerte\">USI</span> / réanimation</strong></p><ul><li>Patient <span class=\"kw-alerte\">tachycarde</span>, saignement actif / abondant, <span class=\"kw-def\">comorbidités</span>, <span class=\"kw-alerte\">état de choc</span></li><li>Appel du <strong>réanimateur</strong></li></ul>","redflags":"<ul><li><span class=\"kw-alerte\">Tachycardie &gt; 100 bpm</span> (attention aux patients sous <span class=\"kw-ttt\">β-bloquants</span>) — meilleur signe précoce</li><li><span class=\"kw-alerte\">Bradycardie</span> (<span class=\"kw-alerte\">signe de gravité</span> extrême) ; <span class=\"kw-alerte\">hypotension</span></li><li>Hypoperfusion périphérique : <span class=\"kw-clinique\">marbrures</span>, <span class=\"kw-clinique\">↑ TRC</span>, <span class=\"kw-clinique\">oligurie</span> <span class=\"kw-chiffre\">&lt; 0,5 mL/kg/h</span></li><li>Retentissement neuro / général : <span class=\"kw-alerte\">confusion</span>, <span class=\"kw-alerte\">agitation</span>, <span class=\"kw-alerte\">coma</span>, <span class=\"kw-clinique\">malaise</span>, <span class=\"kw-clinique\">polypnée</span>, <span class=\"kw-clinique\">pâleur cutanéo-muqueuse</span></li><li>Mauvais rendement transfusionnel : <span class=\"kw-chiffre\">&gt; 2 CGR/24h</span> pour maintenir <span class=\"kw-bio\">Hb &gt; 7 g/dL</span></li></ul>","principes":"<p><strong>Règle d’or :</strong> <span class=\"kw-ttt\">IPP</span> en bolus puis IVSE chez <strong>TOUS</strong> <span class=\"kw-clinique\">les</span> patients d’HD haute (même porteurs d’<span class=\"kw-etio\">HTP</span>), débuté en présomptif dès l’admission <strong>sans retarder l’<span class=\"kw-imagerie\">endoscopie</span></strong> ; rechercher systématiquement <span class=\"kw-bio\">Helicobacter pylori</span> devant toute HD haute.</p><p><strong>Mesures générales</strong></p><ul><li><span class=\"kw-chiffre\">2 VVP</span> de bon calibre + <span class=\"kw-clinique\">oxygénation</span></li><li>Bilan : <span class=\"kw-bio\">NFS</span>, <span class=\"kw-bio\">ionogramme</span>, <span class=\"kw-bio\">créatinine</span>, <span class=\"kw-bio\">calcémie</span>, <span class=\"kw-bio\">hémostase</span>, <span class=\"kw-bio\">2 groupes + RAI</span> ± <span class=\"kw-bio\">GDS</span></li><li>Arrêt ± <span class=\"kw-ttt\">antagonisation</span> des <span class=\"kw-ttt\">anticoagulants</span> ; arrêt de l’<span class=\"kw-ttt\">AAP</span> à discuter avec le cardiologue si <span class=\"kw-alerte\">stent récent (&lt; 1 mois)</span></li></ul><p><strong>HD haute — mesures spécifiques</strong></p><ul><li><span class=\"kw-ttt\">IPP</span> bolus puis IVSE (adaptation au <span class=\"kw-def\">score</span> de <span class=\"kw-def\">Forrest</span>)</li><li>Si <span class=\"kw-etio\">cirrhose</span> / <span class=\"kw-clinique\">HTP</span> : <span class=\"kw-ttt\">octréotide</span> ou <span class=\"kw-ttt\">terlipressine</span> + <span class=\"kw-ttt\">antibioprophylaxie</span> (<span class=\"kw-ttt\">norfloxacine</span> ou <span class=\"kw-ttt\">céfotaxime</span> <span class=\"kw-chiffre\">5-7 j</span>)</li><li>Si <span class=\"kw-etio\">alcoolisme</span> : prévention du <span class=\"kw-ttt\">sevrage</span> par <span class=\"kw-ttt\">vitamines B1 / B6 / PP</span></li></ul><p><strong>Gestes d’hémostase endoscopique</strong></p><ul><li>Pharmacologique : <span class=\"kw-ttt\">sérum adrénaliné</span></li><li>Mécanique : <span class=\"kw-ttt\">clip</span>, <span class=\"kw-ttt\">ligature de varice</span></li><li>Thermique : <span class=\"kw-ttt\">électrocoagulation</span></li></ul><p><strong>En cas d’échec</strong></p><ul><li><span class=\"kw-ttt\">Artério-embolisation</span> en radiologie interventionnelle (si <span class=\"kw-imagerie\">angio-TDM</span> positif)</li><li><span class=\"kw-ttt\">Gastrectomie d’hémostase</span> (exceptionnelle, <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">10-20 %</span>)</li><li><span class=\"kw-ttt\">TIPS</span> si <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-etio\">varices</span> (risque d’<span class=\"kw-alerte\">encéphalopathie hépatique</span>)</li></ul>","suivi":"<p><strong><span class=\"kw-def\">Surveillance</span> :</strong> continue des paramètres vitaux (<span class=\"kw-clinique\">SaO2</span>, <span class=\"kw-clinique\">pouls</span>, <span class=\"kw-clinique\">PA</span>, <span class=\"kw-clinique\">diurèse</span>).<br><strong>Objectifs :</strong> <span class=\"kw-clinique\">FC</span> <span class=\"kw-chiffre\">&lt; 100 bpm</span> · <span class=\"kw-clinique\">PAS &gt; 100 mmHg</span> (ou <span class=\"kw-chiffre\">80-90 mmHg</span> si saignement non contrôlé) · <span class=\"kw-clinique\">diurèse</span> <span class=\"kw-chiffre\">&gt; 0,5 mL/kg/h</span> · <span class=\"kw-bio\">Hb cible</span> <span class=\"kw-chiffre\">7-9 g/dL</span> (<span class=\"kw-chiffre\">7-8</span> si <span class=\"kw-etio\">varices œsophagiennes</span>, <span class=\"kw-chiffre\">&gt; 9</span> si <span class=\"kw-def\">comorbidités</span> cardio-vasculaires).<br><strong><span class=\"kw-def\">Prévention secondaire</span> :</strong> si <span class=\"kw-etio\">varices œsophagiennes</span>, <span class=\"kw-ttt\">octréotide</span> poursuivi puis relais par <span class=\"kw-ttt\">β-bloquants</span> ; éradication d’<span class=\"kw-bio\">H. pylori</span> si <span class=\"kw-etio\">UGD</span> ; <span class=\"kw-def\">réévaluation</span> des <span class=\"kw-ttt\">AINS</span> / <span class=\"kw-ttt\">antithrombotiques</span>.<br><strong>Cirrhotique :</strong> <span class=\"kw-ttt\">antibioprophylaxie</span> <span class=\"kw-chiffre\">5-7 j</span> systématique.</p>"},"liensGlobaux":[{"href":"https://www.ce-mir.fr/sites/www.ce-mir.fr/files/medias/documents/51.%20H%C3%A9morragie%20digestive.pdf","label":"Collège MIR — Hémorragie digestive (chap. 51)"},{"href":"https://radiopaedia.org/articles/gastrointestinal-bleeding?lang=gb","label":"Radiopaedia : Gastrointestinal bleeding"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Hémorragie digestive confirmée — Mesures immédiates : 2 VVP, O₂, scope, NFS / groupe-RAI / hémostase, arrêt ± antagonisation des antithrombotiques","detail":"<h4>CAT — hémorragie digestive — Orientation : <span class=\"kw-alerte\">réanimation</span>, <span class=\"kw-imagerie\">EOGD</span>, alternatives (embolisation, <span class=\"kw-clinique\">TIPS</span>, <span class=\"kw-ttt\">chirurgie</span>)</h4>","branches":[{"to":"q-instable","label":"Instabilité hémodynamique / choc hémorragique (tachycardie, hypotension, marbrures)","color":"red"},{"to":"q-stable","label":"Patient stable (FC normale, pas de saignement actif ni de comorbidité majeure)","color":"green"}]},{"id":"q-instable","kind":"decision","label":"Réanimation + recherche de l’origine — HD haute ou basse ? — Remplissage cristalloïdes ± noradrénaline ± transfusion (Hb cible 7-9 g/dL) ; EOGD seulement après stabilisation","branches":[{"to":"q-varices-echec","label":"HD haute + cirrhose / HTP connue ou suspectée","color":"red"},{"to":"q-eogd-echec","label":"HD haute sans cirrhose (UGD probable)","color":"red"},{"to":"t-angiotdm","label":"HD basse / rectorragies sévères, ou EOGD ne trouve pas l’origine","color":"red"}]},{"id":"q-varices-echec","kind":"decision","label":"<span class=\"kw-imagerie\">EOGD</span> <span class=\"kw-chiffre\">< 12</span>h : hémostase des varices obtenue ?","branches":[{"to":"t-varices-ok","label":"Oui — hémostase obtenue (ligature + vasoactifs)","color":"green"},{"to":"t-tips","label":"Non — échec ou récidive","color":"red"}]},{"id":"t-varices-ok","kind":"terminal","label":"Rupture de varices contrôlée","color":"green","detail":"<h4>Délai</h4><ul><li><span class=\"kw-imagerie\">EOGD</span> en semi-<span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">&lt; 12h</span> (cirrhose / ATCD de varices)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Octréotide</span> (analogue de la somatostatine) ou <span class=\"kw-ttt\">terlipressine</span> dès la suspicion</li><li><span class=\"kw-ttt\">Ligature endoscopique</span> des varices</li><li><span class=\"kw-ttt\">IPP</span> bolus puis IVSE (chez tous, même <span class=\"kw-clinique\">HTP</span>)</li><li><span class=\"kw-ttt\">Antibioprophylaxie</span> : <span class=\"kw-ttt\">norfloxacine</span> ou <span class=\"kw-ttt\">céfotaxime</span> <span class=\"kw-chiffre\">5-7 jours</span></li></ul><h4><span class=\"kw-def\">Prévention secondaire</span></h4><ul><li><span class=\"kw-ttt\">Octréotide</span> poursuivi puis relais par <span class=\"kw-ttt\">β-bloquants</span></li></ul>"},{"id":"t-tips","kind":"terminal","label":"TIPS (shunt porto-systémique)","color":"red","detail":"<h4>Indication</h4><ul><li>Échec de l’hémostase endoscopique ou récidive sur <span class=\"kw-alerte\">rupture</span> de <span class=\"kw-etio\">varices œso-gastriques</span></li></ul><h4>Modalités</h4><ul><li><span class=\"kw-ttt\">TIPS</span> = <span class=\"kw-clinique\">shunt porto-systémique</span> intrahépatique par voie transjugulaire</li></ul><h4>Risque</h4><ul><li>Peut induire ou majorer une <span class=\"kw-alerte\">encéphalopathie hépatique</span></li></ul>"},{"id":"q-eogd-echec","kind":"decision","label":"EOGD : hémostase endoscopique obtenue ?","branches":[{"to":"t-eogd-ok","label":"Oui — hémostase endoscopique obtenue","color":"green"},{"to":"t-gastrectomie","label":"Non — échec ou récidive hémorragique","color":"red"}]},{"id":"t-eogd-ok","kind":"terminal","label":"EOGD d’hémostase réussie","color":"green","detail":"<h4>Geste d’hémostase</h4><ul><li>Pharmacologique : <span class=\"kw-ttt\">sérum adrénaliné</span></li><li>Mécanique : <span class=\"kw-ttt\">clip</span></li><li>Thermique : <span class=\"kw-ttt\">électrocoagulation</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP</span> bolus puis IVSE ; adaptation au <span class=\"kw-def\">score</span> de <span class=\"kw-def\">Forrest</span> (<span class=\"kw-def\">1a-2b</span> → fortes doses IV continu <span class=\"kw-chiffre\">48-72h</span> ; <span class=\"kw-def\">2c-3</span> → relais per os précoce pleine dose)</li></ul><h4>Étiologie</h4><ul><li>Recherche systématique d’<span class=\"kw-bio\">Helicobacter pylori</span></li></ul>"},{"id":"t-gastrectomie","kind":"terminal","label":"Échec : 2ᵉ endoscopie → embolisation / gastrectomie","color":"red","detail":"<h4>2ᵉ tentative</h4><ul><li>Nouvelle <span class=\"kw-imagerie\">endoscopie</span> d’hémostase si persistance ou <span class=\"kw-alerte\">risque vital</span> immédiat</li></ul><h4>Radiologie</h4><ul><li><span class=\"kw-ttt\">Artério-embolisation</span> de l’artère qui saigne si <span class=\"kw-imagerie\">angio-TDM</span> positif</li></ul><h4><span class=\"kw-ttt\">Chirurgie</span></h4><ul><li><span class=\"kw-ttt\">Gastrectomie d’hémostase</span> (exceptionnelle, <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">10-20 %</span>) : échec des autres techniques, <span class=\"kw-alerte\">choc hémorragique non contrôlé</span>, position bulbaire de l’ulcère</li></ul>"},{"id":"t-angiotdm","kind":"terminal","label":"Angio-TDM + artério-embolisation","color":"red","detail":"<h4>Indications</h4><ul><li><span class=\"kw-clinique\">Rectorragies / hématochézies sévères</span> si <span class=\"kw-imagerie\">EOGD</span> non rapidement disponible</li><li><span class=\"kw-alerte\">Fistule aorto-digestive</span> suspectée (ATCD de <span class=\"kw-ttt\">chirurgie</span> de l’aorte abdominale)</li></ul><h4>Geste</h4><ul><li><span class=\"kw-ttt\">Artério-embolisation</span> de l’artère qui saigne en radiologie interventionnelle</li></ul><h4>HD basse avec retentissement</h4><ul><li>PEC initiale identique à l’HD haute (<span class=\"kw-imagerie\">EOGD</span> d’abord, <span class=\"kw-ttt\">IPP</span> sauf si HD haute formellement éliminée)</li></ul>"},{"id":"q-stable","kind":"decision","label":"HD haute ou basse ?","branches":[{"to":"t-semiurgence","label":"HD haute (hématémèse, méléna)","color":"amber"},{"to":"t-coloscopie","label":"HD basse (rectorragie / hématochézie sans retentissement)","color":"amber"}]},{"id":"t-semiurgence","kind":"terminal","label":"<span class=\"kw-imagerie\">EOGD</span> en semi-<span class=\"kw-alerte\">urgence</span> (<span class=\"kw-chiffre\">< 24</span>h)","color":"amber","detail":"<h4>Délai</h4><ul><li><span class=\"kw-imagerie\">EOGD</span> <span class=\"kw-chiffre\">&lt; 24h</span> (HD haute stable, non à risque)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">IPP</span> bolus puis IVSE chez tous, en présomptif dès l’admission</li><li><span class=\"kw-ttt\">Érythromycine IV</span> <span class=\"kw-chiffre\">30-60 min</span> avant (effet prokinétique) — <span class=\"kw-ci\">contre-indiquée si QT long</span></li></ul><h4>Étiologie</h4><ul><li>Recherche systématique d’<span class=\"kw-bio\">Helicobacter pylori</span></li></ul>"},{"id":"t-coloscopie","kind":"terminal","label":"Coloscopie après préparation colique","color":"amber","detail":"<h4>Modalités</h4><ul><li><span class=\"kw-imagerie\">Coloscopie</span> complète après <span class=\"kw-ttt\">préparation colique</span> (régime sans résidus, laxatifs) ; pas d’<span class=\"kw-ttt\">IPP</span> si HD haute formellement éliminée</li></ul><h4>À ne pas oublier</h4><ul><li>Sujet <span class=\"kw-chiffre\">&gt; 50 ans</span> : <span class=\"kw-imagerie\">coloscopie</span> systématique même si l’<span class=\"kw-imagerie\">EOGD</span> a identifié un saignement</li></ul><h4>2ᵉ intention (saignement obscur)</h4><ul><li><span class=\"kw-imagerie\">Vidéocapsule endoscopique</span> ou <span class=\"kw-imagerie\">entéro-TDM</span> (la <span class=\"kw-imagerie\">coloscopie</span> ne dépasse pas l’iléon)</li><li>Pas de <span class=\"kw-bio\">recherche de sang occulte dans les selles</span> (réservée au <span class=\"kw-def\">dépistage</span> de <span class=\"kw-clinique\">masse</span> du CCR)</li></ul>"}]},"cards":[{"i":"78ed8d4a7cb6","n":355,"o":"355-1","u":"Définition","t":"Connaître la définition de l’hémorragie digestive haute et basse","q":"Qu'est-ce qu'une hémorragie digestive ?","a":"<p>Une hémorragie digestive est un saignement ayant pour point de départ une partie du <p>tube digestif</p>.</p>"},{"i":"e0a0fd8f64b0","n":355,"o":"355-1","u":"Définition","t":"Connaître la définition de l’hémorragie digestive haute et basse","q":"Quelle est la définition d'une hémorragie digestive haute et d'une hémorragie digestive basse, et leur proportion respective ?","a":"<ul><li>Une <strong>hémorragie digestive haute</strong> est un saignement qui a lieu <strong>en amont de l'angle de Treitz</strong>. Elle représente environ <strong>80 %</strong> des hémorragies digestives.</li><li>Une <strong>hémorragie digestive basse</strong> est un saignement qui a lieu <strong>en aval de l'angle de Treitz</strong>. Elle représente environ <strong>20 %</strong> des hémorragies digestives.</li></ul>"},{"i":"e444abbf8c82","n":355,"o":"355-1","u":"Définition","t":"Connaître la définition de l’hémorragie digestive haute et basse","q":"Quel est le repère anatomique qui sépare une hémorragie digestive haute d'une hémorragie digestive basse ?","a":"<p>Le repère anatomique qui sépare une hémorragie digestive haute d'une hémorragie digestive basse est l'<strong>angle duodéno-jéjunal</strong> (ou <strong>angle de Treitz</strong>).</p>"},{"i":"b8a8e7a8759b","n":355,"o":"355-11","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hémorragie digestive haute ou basse chez l’adulte et l’enfant","q":"Quels sont les signes de gravité majeurs à rechercher lors d'une hémorragie digestive ?","a":"<ul><li><strong>Tachycardie supérieure à 100 bpm</strong> (attention aux patients sous bêta-bloquants).</li><li><strong>Bradycardie</strong>, qui est un signe de gravité extrême.</li><li><strong>Hypotension artérielle</strong>.</li><li>Signes d'<strong>hypoperfusion périphérique</strong> : marbrures, augmentation du Temps de Recoloration Cutanée (TRC), oligurie.</li><li>Signes généraux et neurologiques : malaise, confusion, agitation, coma, lipothymie, chute, polypnée, pâleur cutanéo-muqueuse.</li></ul>"},{"i":"cc98f56477d1","n":355,"o":"355-11","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hémorragie digestive haute ou basse chez l’adulte et l’enfant","q":"Quel est le signe hémodynamique précoce le plus pertinent témoignant d'une défaillance hémodynamique débutante lors d'une hémorragie digestive ?","a":"<p>La <strong>tachycardie</strong> est le meilleur signe précoce de défaillance hémodynamique débutante devant toute hémorragie. Elle constitue un signe d'alerte majeur.</p>"},{"i":"fd0bef3cee83","n":355,"o":"355-11","u":"Identifier une urgence","t":"Connaître les signes de gravité d’une hémorragie digestive haute ou basse chez l’adulte et l’enfant","q":"Quels sont les pièges à éviter lors de l'évaluation de la gravité d'une hémorragie digestive ?","a":"<ul><li>La <strong>quantité de sang extériorisé est un mauvais critère</strong> et ne permet pas d'estimer la gravité.</li><li>Le taux d'<strong>hémoglobine (Hb) et l'hématocrite sous-estiment initialement l'abondance</strong> réelle de l'hémorragie.</li><li>La gravité peut être sous-estimée chez le <strong>sujet jeune</strong> qui compense l'hypovolémie par une tachycardie, retardant l'apparition de l'hypotension.</li></ul>"},{"i":"1cf2a8b467ee","n":355,"o":"355-12","u":"Identifier une urgence","t":"Connaître les diagnostics urgents devant une hémorragie digestive basse : invagination intestinale aiguë (basse), diverticule de Meckel","q":"Quelles sont les deux étiologies urgentes pédiatriques à rechercher devant une hémorragie digestive basse, comme indiqué dans l'item 355 ?","a":"<p>Les deux étiologies urgentes pédiatriques à rechercher devant une hémorragie digestive basse sont l'<strong>invagination intestinale aiguë (basse)</strong> et le <strong>diverticule de Meckel</strong>.</p>"},{"i":"b500549c2c25","n":355,"o":"355-12","u":"Identifier une urgence","t":"Connaître les diagnostics urgents devant une hémorragie digestive basse : invagination intestinale aiguë (basse), diverticule de Meckel","q":"Quels sont les signes cliniques et la prise en charge initiale d'une invagination intestinale aiguë (basse) en pédiatrie face à une hémorragie digestive basse ?","a":"<p>L'invagination intestinale aiguë (basse) est une urgence, surtout chez le nourrisson, se révélant par une <strong>occlusion intestinale</strong>, parfois associée à une hémorragie. La prise en charge initiale consiste en une <strong>réduction par lavement</strong>, qui peut être à la fois diagnostique et thérapeutique.</p>"},{"i":"de8201d70aab","n":355,"o":"355-12","u":"Identifier une urgence","t":"Connaître les diagnostics urgents devant une hémorragie digestive basse : invagination intestinale aiguë (basse), diverticule de Meckel","q":"Quelle est la physiopathologie principale du diverticule de Meckel en tant que cause d'hémorragie digestive et quelle est sa prise en charge thérapeutique ?","a":"<p>Le diverticule de Meckel est la <strong>première cause d'hémorragie digestive du grêle</strong> (40% des cas) et sa révélation se fait volontiers par hémorragie (plutôt chez l'adulte) ou par occlusion (plutôt chez l'enfant). La prise en charge thérapeutique est chirurgicale.</p>"},{"i":"34f8ce82d991","n":355,"o":"355-13","u":"Prise en charge","t":"Connaître et prévenir les principaux facteurs de risques de saignement","q":"Comment les antithrombotiques (Aspirine et autres) influencent-ils le risque d'hémorragie digestive ?","a":"<p>L'<strong>Aspirine</strong> présente une toxicité digestive <strong>dose-dépendante</strong>, même à faibles doses. Les <strong>autres antiagrégants plaquettaires</strong> et les <strong>anticoagulants</strong> aggravent le saignement de lésions digestives préexistantes, qu'elles soient hautes ou basses.</p>"},{"i":"35aa0051514c","n":355,"o":"355-13","u":"Prise en charge","t":"Connaître et prévenir les principaux facteurs de risques de saignement","q":"Comment l'infection à Helicobacter pylori est-elle un facteur de risque d'hémorragie digestive ?","a":"<p>L'infection par <strong>Helicobacter pylori</strong> doit être systématiquement recherchée en cas d'hémorragie digestive haute, car elle est une cause fréquente d'ulcères gastroduodénaux, sources de saignements.</p>"},{"i":"5c5fab323aca","n":355,"o":"355-13","u":"Prise en charge","t":"Connaître et prévenir les principaux facteurs de risques de saignement","q":"Quel est le mécanisme par lequel les antidépresseurs sérotoninergiques (ISRS) augmentent le risque hémorragique digestif ?","a":"<p>Les <strong>ISRS</strong> (inhibiteurs sélectifs de la recapture de la sérotonine) augmentent le risque hémorragique digestif par un <strong>blocage de la recapture plaquettaire de sérotonine</strong>, entraînant un trouble de l'<strong>hémostase primaire</strong>. Ce risque est accru chez le sujet âgé, en cas d'antécédents ulcéreux, ou en co-prescription d'AINS.</p>"},{"i":"6af1eac63fb4","n":355,"o":"355-13","u":"Prise en charge","t":"Connaître et prévenir les principaux facteurs de risques de saignement","q":"Quel est l'impact des AINS sur le risque d'hémorragie digestive et quelle est la spécificité des anti-COX2 ?","a":"<p>Les <strong>AINS</strong> augmentent le risque de complications ulcéreuses d'un facteur <strong>3 à 4</strong> et les complications fatales d'un facteur <strong>7 à 8</strong>. Ils favorisent également les hémorragies digestives basses. Les <strong>anti-COX2</strong> réduisent de <strong>50 %</strong> les événements gastro-intestinaux graves par rapport aux AINS non sélectifs.</p>"},{"i":"ce7984926cfb","n":355,"o":"355-13","u":"Prise en charge","t":"Connaître et prévenir les principaux facteurs de risques de saignement","q":"Quel facteur de risque d'hémorragie digestive est lié à l'hypertension portale et quel est son impact ?","a":"<p>L'<strong>hypertension portale</strong> est un facteur de risque majeur d'hémorragie digestive par rupture de <strong>varices œsophagiennes</strong>.</p>"},{"i":"0186b5b9d583","n":355,"o":"355-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique en urgence des hémorragies digestives et de leurs complications y compris chez le cirrhotique","q":"Quelles sont les options thérapeutiques en cas d'échec de la prise en charge endoscopique pour une hémorragie digestive ?","a":"<p>En cas d'échec de l'endoscopie, les options sont :</p><ul><li><strong>Artério-embolisation</strong> en radiologie interventionnelle, si l'angio-scanner (angio-TDM) est positif.</li><li><strong>Gastrectomie d'hémostase</strong> (exceptionnelle, mortalité 10-20 %) si choc initial non contrôlé ou position bulbaire de l'ulcère.</li><li><strong>TIPS</strong> (shunt porto-systémique transjugulaire intrahépatique) pour la rupture de varices œso-gastriques, mais avec un risque d'induire/majorer une encéphalopathie hépatique, surtout chez le cirrhotique.</li><li>Chez le cirrhotique avec rupture de varices œsophagiennes, l'<strong>octréotide</strong> est poursuivi puis relayé par des <strong>bêta-bloquants</strong> en prévention secondaire, et une <strong>antibioprophylaxie systématique</strong> est maintenue.</li></ul>"},{"i":"12d01256d883","n":355,"o":"355-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique en urgence des hémorragies digestives et de leurs complications y compris chez le cirrhotique","q":"Quelle est la prise en charge spécifique en cas de choc hémorragique secondaire à une hémorragie digestive et quels sont les objectifs de cette réanimation ?","a":"<p>En cas de choc hémorragique :</p><ul><li><strong>Remplissage vasculaire</strong> par <strong>cristalloïdes</strong>.</li><li><strong>Noradrénaline</strong> si la PA systolique (PAS) reste basse malgré <strong>1-1,5 L de remplissage</strong>.</li><li><strong>Transfusion sanguine</strong> selon les objectifs définis.</li></ul><p>Les objectifs de réanimation sont :</p><ul><li>Fréquence cardiaque : <strong>normale</strong>.</li><li><strong>PAS &gt; 100 mmHg ou Pression Artérielle Moyenne (PAM) ≥ 65 mmHg</strong> (sauf en cas de saignement non contrôlé où l'on vise <strong>PAS 80-90 mmHg</strong>).</li><li>Diurèse <strong>&gt; 30 mL/h</strong> (ou &gt; 0,5 mL/kg/h).</li><li>Hémoglobine (Hb) cible : <strong>7-9 g/dL en général</strong> ; <strong>7-8 g/dL si varices œsophagiennes</strong> ; <strong>&gt; 9 g/dL si comorbidités cardio-vasculaires</strong>.</li></ul>"},{"i":"14faf2c67a12","n":355,"o":"355-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique en urgence des hémorragies digestives et de leurs complications y compris chez le cirrhotique","q":"Quel est le rôle de l'endoscopie œso-gastro-duodénale (EOGD) et des gestes d'hémostase dans la prise en charge de l'hémorragie digestive ?","a":"<p>Le rôle de l'EOGD est crucial :</p><ul><li><strong>Timing</strong> : Après stabilisation du patient instable ; en urgence si HD haute active instable ou rectorragies sévères ; en semi-urgence (HD haute stable) ou si suspicion de rupture de varices œsophagiennes.</li><li><strong>Préparation</strong> : Administration d'<strong>érythromycine IV 30-60 minutes avant</strong> (effet prokinétique) – contre-indiquée si QT long.</li><li><strong>Gestes d'hémostase</strong> : Peuvent être <strong>pharmacologiques</strong> (sérum adrénaliné), <strong>mécaniques</strong> (clip, ligature de varice) ou <strong>thermiques</strong> (électrocoagulation).</li></ul>"},{"i":"5251f1062197","n":355,"o":"355-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique en urgence des hémorragies digestives et de leurs complications y compris chez le cirrhotique","q":"Quelles sont les mesures médicamenteuses spécifiques de l'hémorragie digestive haute ?","a":"<p>Les mesures médicamenteuses spécifiques incluent :</p><ul><li><strong>Inhibiteurs de la pompe à protons (IPP)</strong> : <strong>bolus puis IVSE</strong> chez TOUS les patients d'HD haute (même porteurs d'Hypertension Portale - HTP), en présomptif dès l'admission sans retarder l'endoscopie. L'adaptation se fait selon le score de Forrest.</li><li><strong>Octréotide</strong> (analogue de la somatostatine) ou <strong>terlipressine</strong> (analogue de la vasopressine) : en pré-hospitalier (si HTP) si hépatopathie chronique ou HTP connue/suspectée.</li><li><strong>Antibioprophylaxie</strong> (si cirrhose / HTP) : <strong>norfloxacine</strong> ou <strong>céfotaxime</strong> pendant <strong>5-7 jours</strong>.</li><li><strong>Prévention du syndrome de sevrage</strong> (si alcoolisme) : <strong>hydratation + vitamines B1 / B6 / PP</strong>.</li></ul>"},{"i":"9c0c66ea7c64","n":355,"o":"355-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique en urgence des hémorragies digestives et de leurs complications y compris chez le cirrhotique","q":"Quelles sont les premières mesures de réanimation à mettre en œuvre en urgence face à une hémorragie digestive ?","a":"<p>Les premières mesures de réanimation comprennent :</p><ul><li>Mise en place de <strong>2 voies veineuses périphériques (VVP) de bon calibre</strong> et assurer une <strong>bonne oxygénation</strong>.</li><li>Surveillance continue : <strong>SaO2, pouls, pression artérielle (PA), diurèse</strong>.</li><li>Bilan biologique : <strong>NFS, ionogramme, créatininémie, calcémie, hémostase, bilan pré-transfusionnel</strong> (&gt;2 Groupes Sanguins + RAI) ± GDS.</li><li>Gestion des antithrombotiques : <strong>arrêt</strong> et potentiellement <strong>antagonisation des anticoagulants</strong>; <strong>arrêt de l'antiagrégant plaquettaire (AAP)</strong> à discuter avec le cardiologue si stent récent.</li></ul>"},{"i":"c13cffdd6be9","n":355,"o":"355-14","u":"Prise en charge","t":"Connaître les principes de la prise en charge thérapeutique en urgence des hémorragies digestives et de leurs complications y compris chez le cirrhotique","q":"Comment doit être orienté un patient présentant une hémorragie digestive en fonction de son état clinique initial ?","a":"<ul><li>Si le patient est <strong>stable</strong> (fréquence cardiaque normale, sans saignement actif, sans forte déglobulisation ni comorbidité majeure), il sera orienté vers une <strong>hospitalisation en service conventionnel</strong>.</li><li>Si le patient est <strong>tachycarde, présente un saignement actif/abondant, des comorbidités ou un état de choc</strong>, il nécessite un <strong>appel du réanimateur</strong> et une hospitalisation en <strong>Unité de Soins Intensifs (USI) / réanimation</strong>.</li></ul>"},{"i":"397d588631de","n":355,"o":"355-3","u":"Diagnostic positif","t":"Connaître les modes de révélation clinique (hématémèse, méléna, hématochézie, choc hémorragique)","q":"Comment définir cliniquement l'hématémèse et quelle est sa valeur localisatrice dans le cadre d'une hémorragie digestive ?","a":"<p>L'hématémèse est l'extériorisation de sang lors d'un effort de vomissement. Elle traduit toujours une <strong>hémorragie digestive haute</strong>.</p>"},{"i":"3dc18706179f","n":355,"o":"355-3","u":"Diagnostic positif","t":"Connaître les modes de révélation clinique (hématémèse, méléna, hématochézie, choc hémorragique)","q":"Qu'est-ce que l'hématochézie (ou rectorragie) et quelles sont ses significations en termes d'origine d'hémorragie digestive ?","a":"<p>L'hématochézie, ou rectorragie, correspond à l'évacuation de <strong>sang rouge</strong> par l'anus.</p><p>Elle signe soit une <strong>hémorragie digestive basse</strong>, soit une <strong>hémorragie digestive haute massive</strong> (par exemple, un ulcère duodénal érodant l'artère duodénale postérieure).</p>"},{"i":"a73dae4603a0","n":355,"o":"355-3","u":"Diagnostic positif","t":"Connaître les modes de révélation clinique (hématémèse, méléna, hématochézie, choc hémorragique)","q":"Comment doit-on suspecter et diagnostiquer un choc hémorragique sans extériorisation dans le cadre d'une hémorragie digestive ?","a":"<p>Il doit être suspecté devant des signes de choc tels que la <strong>tachycardie</strong> et l'<strong>hypotension</strong>, associés à un <strong>mauvais rendement transfusionnel</strong> (plus de 2 CGR en 24h pour maintenir l'Hb > 7 g/dL).</p><p>Le diagnostic repose sur la mise en place d'une <strong>sonde gastrique</strong> et la recherche de sang au <strong>toucher rectal</strong>.</p>"},{"i":"d5addf0546e5","n":355,"o":"355-3","u":"Diagnostic positif","t":"Connaître les modes de révélation clinique (hématémèse, méléna, hématochézie, choc hémorragique)","q":"Quelle est la définition clinique du méléna et quelles sont ses origines possibles dans le contexte d'une hémorragie digestive ?","a":"<p>Le méléna est l'émission par l'anus de sang <strong>digéré, noir et fétide</strong> (aspect goudron). Il peut passer inaperçu et doit être recherché au toucher rectal.</p><p>Son origine est généralement en amont de l'angle colique droit, signant une hémorragie digestive <strong>haute dans 80% des cas</strong>, mais il peut aussi être d'origine basse.</p>"},{"i":"41da3476f994","n":355,"o":"355-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hémorragie digestive haute ou basse","q":"Comment la rectorragie ou l'hématochézie se présente-t-elle et quelle est sa signification quant au siège de l'hémorragie digestive ?","a":"<p>La rectorragie ou l'hématochézie se manifeste par l'émission de <strong>sang rouge</strong>. Elle est généralement le signe d'une hémorragie digestive <strong>basse</strong>, mais elle peut également survenir en cas d'hémorragie digestive haute <strong>massive</strong>.</p>"},{"i":"84099738e111","n":355,"o":"355-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hémorragie digestive haute ou basse","q":"Quels sont les principaux diagnostics différentiels à éliminer devant une extériorisation de sang par voie digestive ?","a":"<p>Les principaux diagnostics différentiels sont :</p><ul><li>Pour l'<strong>hématémèse</strong> : une <strong>hémoptysie</strong>, une <strong>épistaxis postérieure déglutie</strong>, ou la consommation de <strong>vomissements alimentaires rouges</strong> (vin rouge, betteraves, grenadine).</li><li>Pour l'<strong>hémorragie digestive basse</strong> : une <strong>ulcération thermométrique</strong> (en pédiatrie) ou la <strong>supplémentation en fer</strong> (responsable d'un faux méléna).</li></ul>"},{"i":"920a4d1e6e90","n":355,"o":"355-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hémorragie digestive haute ou basse","q":"Dans quel contexte évoquer une hémorragie digestive en l'absence d'extériorisation de sang, et comment le diagnostic peut-il être orienté ?","a":"<p>Une hémorragie digestive doit être évoquée en présence d'un <strong>choc</strong> (avec tachycardie, hypotension) sans extériorisation visible de sang, ou en cas de <strong>mauvais rendement transfusionnel</strong> inexpliqué. Le diagnostic peut être orienté par la mise en place d'une <strong>sonde nasogastrique (SNG)</strong> ou la réalisation d'un <strong>toucher rectal (TR)</strong>.</p>"},{"i":"bc8c95d8120b","n":355,"o":"355-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hémorragie digestive haute ou basse","q":"Comment l'hématémèse se présente-t-elle cliniquement et quelle est sa signification quant au siège de l'hémorragie digestive ?","a":"<p>L'hématémèse se caractérise par l'émission de <strong>sang rouge ou digéré</strong> lors d'un effort de vomissement. Elle est un signe évocateur d'une <strong>hémorragie digestive haute</strong>.</p>"},{"i":"c5205067e23d","n":355,"o":"355-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hémorragie digestive haute ou basse","q":"Comment le méléna se présente-t-il et quelle est sa signification quant au siège de l'hémorragie digestive ? Quel piège diagnostique est à connaître ?","a":"<p>Le méléna correspond à l'émission de <strong>selles noires et fétides</strong>. Il est généralement le signe d'une hémorragie digestive <strong>haute</strong> (80% des cas), mais peut aussi être causé par une hémorragie digestive basse. Un piège diagnostique est la <strong>supplémentation en fer</strong> par voie orale qui noircit les selles et simule un méléna.</p>"},{"i":"db1a3fdbe829","n":355,"o":"355-4","u":"Diagnostic positif","t":"Connaître les éléments du diagnostic d’une hémorragie digestive haute ou basse","q":"Comment la sonde nasogastrique (SNG) contribue-t-elle au diagnostic d'une hémorragie digestive haute, et quelles sont ses limites ?","a":"<p>La <strong>sonde nasogastrique (SNG)</strong> affirme le diagnostic d'hémorragie digestive haute si elle ramène un <strong>liquide sanglant vif</strong>. Cependant, l'<strong>absence de saignement</strong> dans la SNG n'élimine pas une hémorragie digestive haute si celle-ci est <strong>post-bulbaire</strong>.</p>"},{"i":"95a49d8ba3a9","n":355,"o":"355-7","u":"Etiologies","t":"Savoir que la cause la plus fréquente d’hémorragie digestive haute est l’ulcération gastro duodénale","q":"Face à une hémorragie digestive haute, quel diagnostic doit être évoqué en priorité et quelle étiologie doit être systématiquement recherchée ?","a":"<p>Face à une hémorragie digestive haute, le premier diagnostic à évoquer est l'<strong>ulcération gastro-duodénale (UGD)</strong>. La recherche de l'infection par <strong><em>Helicobacter pylori</em></strong> doit être systématique.</p>"},{"i":"c5ae0adadcd4","n":355,"o":"355-7","u":"Etiologies","t":"Savoir que la cause la plus fréquente d’hémorragie digestive haute est l’ulcération gastro duodénale","q":"Quelle est la cause la plus fréquente d'hémorragie digestive haute ?","a":"<p>La cause la plus fréquente d'hémorragie digestive haute est l'<strong>ulcération gastro-duodénale</strong>.</p>"},{"i":"dde8863392ff","n":355,"o":"355-7","u":"Etiologies","t":"Savoir que la cause la plus fréquente d’hémorragie digestive haute est l’ulcération gastro duodénale","q":"Quel pourcentage des hémorragies digestives hautes sont dues à une ulcération gastro-duodénale ?","a":"<p>Les ulcérations gastro-duodénales sont responsables de <strong>30 à 60 %</strong> des hémorragies digestives hautes.</p>"},{"i":"60d909299a23","n":355,"o":"355-8","u":"Etiologies","t":"Connaître les principales causes d’hémorragie digestives","q":"Quelles sont les étiologies principales d'une hémorragie digestive haute ?","a":"<p>Les causes principales d'hémorragie digestive haute sont :</p><ul><li>Les <strong>ulcères/ulcérations gastro-duodénales</strong> (30-60%).</li><li>Les <strong>érosions gastro-duodénales</strong> (7-20%).</li><li>La <strong>rupture de varices œsophagiennes ou cardio-tubérositaires</strong>, et la gastropathie d'hypertension portale (3-20%).</li></ul>"},{"i":"6370d855ba8a","n":355,"o":"355-8","u":"Etiologies","t":"Connaître les principales causes d’hémorragie digestives","q":"Devant une hémorragie digestive basse, quelle étiologie doit être éliminée systématiquement et quel est le piège diagnostique à éviter concernant les hémorroïdes ?","a":"<p>Devant une hémorragie digestive basse, la <strong>tumeur colo-rectale doit être éliminée systématiquement</strong>. La maladie hémorroïdaire, même si elle est présente, ne doit jamais dispenser d'une <strong>coloscopie complète</strong> pour rechercher une autre cause sous-jacente.</p>"},{"i":"886998426c66","n":355,"o":"355-8","u":"Etiologies","t":"Connaître les principales causes d’hémorragie digestives","q":"Quelles sont les étiologies d'hémorragie digestive basse du grêle ?","a":"<p>Les étiologies d'hémorragie digestive basse touchant l'intestin grêle incluent :</p><ul><li>Le <strong>diverticule de Meckel</strong> (40%).</li><li>Les <strong>angiodysplasies</strong>.</li><li>Les <strong>ulcérations</strong> (favorisées par les AINS).</li><li>Les <strong>MICI</strong> (maladies inflammatoires chroniques de l'intestin, notamment la maladie de Crohn en poussée).</li><li>Les <strong>tumeurs</strong>.</li><li>La <strong>maladie de Rendu-Osler</strong>.</li></ul>"},{"i":"c42a11034e8e","n":355,"o":"355-8","u":"Etiologies","t":"Connaître les principales causes d’hémorragie digestives","q":"Quelles sont les étiologies d'hémorragie digestive basse du côlon-rectum-anus et quelle est la cause la plus fréquente ?","a":"<p>Les étiologies d'hémorragie digestive basse du côlon-rectum-anus sont :</p><ul><li>La <strong>maladie diverticulaire</strong> (1ʳᵉ cause, 40%).</li><li>La <strong>tumeur colique ou rectale</strong> (maligne à éliminer systématiquement).</li><li>Les <strong>colites</strong> (ischémiques, infectieuses, radiques, MICI).</li><li>Les <strong>angiodysplasies coliques</strong>.</li><li>La <strong>maladie hémorroïdaire</strong>.</li><li>La <strong>fissure anale</strong>.</li><li>L'hémorragie digestive basse sur <strong>hypertension portale</strong>.</li></ul>"},{"i":"d9bbc012edb2","n":355,"o":"355-8","u":"Etiologies","t":"Connaître les principales causes d’hémorragie digestives","q":"En dehors des causes principales, quelles autres étiologies d'hémorragie digestive haute doivent être connues pour l'EDN ?","a":"<p>D'autres étiologies d'hémorragie digestive haute à connaître sont :</p><ul><li>L'<strong>œsophagite</strong> (peptique, médicamenteuse, caustique) (1-10%).</li><li>Les <strong>cancers du tractus digestif supérieur</strong> (2-5%).</li><li>Le <strong>syndrome de Mallory-Weiss</strong> (2-4%), généralement précédé de vomissements.</li></ul>"},{"i":"ff9b682f55e4","n":355,"o":"355-8","u":"Etiologies","t":"Connaître les principales causes d’hémorragie digestives","q":"Quelles sont les causes plus rares d'hémorragie digestive haute ?","a":"<p>Parmi les causes plus rares d'hémorragie digestive haute, on trouve :</p><ul><li>Les <strong>gastrites</strong>.</li><li>Les <strong>angiodysplasies</strong>.</li><li>L'<strong>ulcération de Dieulafoy</strong> (ulcération en regard d'une artère sous-muqueuse dilatée).</li><li>Les <strong>hémobilies</strong>, les <strong>wirsungorragies</strong> et les <strong>fistules aorto-digestives</strong>.</li></ul>"},{"i":"1344751bf8a0","n":355,"o":"355-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à réaliser devant une hémorragie digestive","q":"Quels sont les éléments clés du bilan pré-transfusionnel à réaliser devant une hémorragie digestive ?","a":"<p>Les éléments clés du bilan pré-transfusionnel devant une hémorragie digestive sont :</p><ul><li><strong>Deux déterminations du groupe sanguin</strong> (à réaliser sur deux prélèvements différents).</li><li>La <strong>Recherche d'Agglutinines Irrégulières (RAI)</strong>.</li></ul>"},{"i":"295605403cce","n":355,"o":"355-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à réaliser devant une hémorragie digestive","q":"Quels sont les examens biologiques essentiels à réaliser en urgence devant une hémorragie digestive, et quel est le piège lié à la numération formule sanguine (NFS) ?","a":"<p>Les examens biologiques essentiels devant une hémorragie digestive sont :</p><ul><li>La <strong>NFS</strong> (hémoglobine, hématocrite) : peut initialement <strong>sous-estimer l'abondance du saignement</strong>.</li><li><strong>Ionogramme sanguin</strong>, <strong>créatinine</strong>, <strong>calcémie</strong>.</li><li>Bilan d'hémostase : <strong>TP</strong>, <strong>TCA</strong>, <strong>plaquettes</strong>, <strong>fibrinogène</strong>.</li><li>Bilan <strong>pré-transfusionnel</strong> : <strong>2 déterminations de groupe sanguin</strong> et <strong>RAI</strong> (Recherche d'Agglutinines Irrégulières).</li><li><strong>Gaz du sang</strong> : à discuter selon l'état clinique du patient.</li></ul><p>Le piège est qu'une <strong>hémoglobine normale à l'arrivée n'élimine pas une hémorragie grave</strong>, car elle peut être initialement normale par hémoconcentration.</p>"},{"i":"de88b5aed559","n":355,"o":"355-9","u":"Examens complémentaires","t":"Connaître les examens biologiques à réaliser devant une hémorragie digestive","q":"Pourquoi la concentration d'hémoglobine lors de la prise de sang initiale peut-elle être trompeuse quant à l'abondance du saignement dans une hémorragie digestive ?","a":"<p>La concentration d'hémoglobine initiale peut sous-estimer l'abondance réelle du saignement en raison de l'<strong>hémoconcentration</strong>. Le volume plasmatique n'étant pas encore significativement impacté ou compensé par un remplissage, les valeurs d'hémoglobine et d'hématocrite peuvent paraître normales, alors qu'une perte sanguine importante a déjà eu lieu.</p>"}]};